function cameraScope2(device,tracker=[]){let activation=normalized3(device.activation_state),org=normalized3(device.organization),unit=normalized3(device.unit_key);if(device.__ownerPlacement==="FIELD"||device.__ownerPlacement==="SHOP"||device.__ownerPlacement==="UNKNOWN")return device.__ownerPlacement.toLowerCase();if(/^STOLEN FROM RII?[-\s]*\d+ ON \d{2}\/\d{2}\/\d{4}$/.test(unit)||/^STOLEN FROM RII?[-\s]*\d+ ON \d{2}\/\d{2}\/\d{4}$/.test(org)||["RETIRED","STOLEN","NOT IN USE"].includes(org)||/^RII?[-\s]*\d+\s*-?\s*(?:NOT IN USE|RETIRED|STOLEN)$/.test(unit))return"inactive";if(["ROOT","SHOP","SHOP/ROOT","ROOT/SHOP","SHOP / ROOT","ROOT / SHOP","SHOP EQUIPMENT"].includes(org)||unit==="SHOP EQUIPMENT"||/^RII?[-\s]*\d+\s*-?\s*SHOP$/.test(unit))return"shop";if(activation==="DEACTIVATED")return"inactive";if(activation!=="ACTIVE")return"unknown";let matches2=tracker.filter(row2=>normalized3(row2.source_label)===unit);return matches2.length>1||matches2.some(row2=>["shop","retired"].includes(row2.tracker_state))||device.__trackerOnly||!org||["TRACKER FIELD","TRACKER \xB7 SITE NOT LINKED","UNKNOWN","FIELD OR UNKNOWN"].includes(org)?"unknown":"field"}
